<script lang="ts">
import {onMount,onDestroy} from 'svelte';
import {api,type Book,type Shelf} from '../../lib/api';
type Subject={name:string;count:number};
let subject='';let subjectSearch='';let subjects:Subject[]=[];let subjectError='';let subjectsReady=false;let sort='title';
$: matchingSubjects=subjects.filter(s=>s.name.toLocaleLowerCase().includes(subjectSearch.trim().toLocaleLowerCase()));
$: visibleSubjects=matchingSubjects.slice(0,20);
let books:Book[]=[];let shelves:Shelf[]=[];let q='';let shelf='';let available='';let page=1;let total=0;let loading=true;let error='';let sequence=0;let searchInput:HTMLInputElement;let debounce:ReturnType<typeof setTimeout>;let focused=false;
async function load(){const seq=++sequence;loading=true;error='';try{const v=await api<{books:Book[];total:number}>(`/api/books?${new URLSearchParams({q,shelf_id:shelf,availability:available,subject,sort,page:String(page)})}`);if(seq!==sequence)return;books=v.books;total=v.total;}catch(e){if(seq===sequence)error=(e as Error).message;}finally{if(seq===sequence)loading=false;}}
function search(e:SubmitEvent){e.preventDefault();clearTimeout(debounce);const code=q.replace(/[\s-]/g,'').toUpperCase();if(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(code)){window.location.href=`/scan/?isbn=${encodeURIComponent(code)}`;return;}page=1;load();}
function typed(){clearTimeout(debounce);if(/^[\d\s-]+[Xx]?$/.test(q))return;debounce=setTimeout(()=>{page=1;load();},200);}
function clear(){clearTimeout(debounce);q='';page=1;load();searchInput.focus();}
function filter(){page=1;load();}
function mainTitle(title:string){return title.split(/:\s+|\s+(?=Proven Strategies For\b)/i)[0];}
function authorLabel(authors:string[]){return authors.length>1?`${authors[0]} & others`:authors[0]||'Author not recorded';}
function locationLabel(path:string){const [caseName,shelfName]=path.split(' / ');return shelfName&&caseName.toLowerCase().split(/\W+/).includes(shelfName.toLowerCase())?caseName:path.replace(' / ',' · ');}
onMount(()=>{subject=new URLSearchParams(window.location.search).get('subject')||'';searchInput.focus();load();api<Shelf[]>('/api/shelves').then(v=>shelves=v).catch(()=>{});api<{subjects:Subject[]}>('/api/book-subjects').then(v=>subjects=v.subjects.filter(s=>!/^(?:nyt:|reading_level:|collection:|open_syllabus:)/i.test(s.name)).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name))).catch(()=>subjectError='Subjects could not be loaded. Refresh to try again.').finally(()=>subjectsReady=true);const focus=()=>load();window.addEventListener('focus',focus);return()=>window.removeEventListener('focus',focus);});
onDestroy(()=>clearTimeout(debounce));
</script>
<div class="catalogue_wrap">
<form class="catalogue_tools" onsubmit={search} role="search">
<header class="catalogue_header"><div class="catalogue_title"><h1>Your books</h1><span aria-live="polite">{loading?'Loading…':`${total} ${total===1?'book':'books'}`}</span></div><div class="catalogue_search-group"><label for="library-search" class="catalogue_label">Scan or search for a book</label>
<div class="catalogue_search" class:focused>
<svg class="catalogue_scan-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 8V4h4 M17 4h4v4 M21 16v4h-4 M7 20H3v-4 M7 8v8 M10 7v10 M14 7v10 M17 8v8"/></svg>
<input id="library-search" class="catalogue_input" type="search" bind:this={searchInput} bind:value={q} oninput={typed} onfocus={()=>focused=true} onblur={()=>focused=false} placeholder="Scan ISBN, or search title or author" aria-describedby="search-help"/>
{#if q}<button class="catalogue_clear" type="button" onclick={clear} aria-label="Clear search">×</button>{/if}
<button class="catalogue_submit" type="submit" aria-label="Find book">Find</button>
</div></div><details class="catalogue_advanced"><summary><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16 M7 12h10 M10 17h4"/></svg>Filters{#if shelf||available||subject}<span class="catalogue_filter-dot" aria-label="Filters active"></span>{/if}</summary><div class="catalogue_filters"><label class="library-field">Shelf<select bind:value={shelf} onchange={filter}><option value="">All shelves</option>{#each shelves as s}<option value={s.id}>{s.bookcase} / {s.name}</option>{/each}</select></label><label class="library-field">Availability<select bind:value={available} onchange={filter}><option value="">All books</option><option value="available">Available</option></select></label>{#if shelf||available||subject}<button class="library-button secondary" type="button" onclick={()=>{shelf='';available='';subject='';filter();}}>Reset filters</button>{/if}</div></details></header>
<p id="search-help" class="catalogue_hint">Scan an ISBN to open a book. Titles, subtitles and authors search as you type.</p>
</form>
<div class="catalogue_browse">
<details class="catalogue_subjects" open={!!subject}><summary>Browse by subject{#if subject}: {subject}{/if}</summary>
<div class="catalogue_subject-body"><p>Subjects come from book records and may overlap. They do not change your shelves.</p>
<label class="library-field">Find a subject<input type="search" bind:value={subjectSearch} placeholder="Search subjects"/></label>
{#if subject}<button type="button" class="library-button secondary" onclick={()=>{subject='';filter();}}>Clear subject: {subject}</button>{/if}
{#if subjectError}<p role="alert" class="library-error">{subjectError}</p>{:else if !subjectsReady}<p role="status">Loading subjects…</p>{:else if !subjects.length}<p>No subjects recorded yet. Use “Fill empty fields from Open Library” on a book to add them.</p>{:else}<ul class="catalogue_subject-list">{#each visibleSubjects as item}<li><button type="button" aria-pressed={subject===item.name} onclick={()=>{subject=item.name;filter();}}>{item.name} <span>{item.count} {item.count===1?'book':'books'}</span></button></li>{/each}</ul>
{#if matchingSubjects.length>20}<p>Showing 20 of {matchingSubjects.length} subjects. Type above to narrow the list.</p>{:else if !matchingSubjects.length}<p>No matching subjects.</p>{/if}{/if}</div></details>
<label class="library-field catalogue_sort">Sort by<select bind:value={sort} onchange={filter}><option value="title">Title A–Z</option><option value="author">Author A–Z</option><option value="published_newest">Edition published: newest</option><option value="published_oldest">Edition published: oldest</option><option value="first_published_newest">First published: newest</option><option value="first_published_oldest">First published: oldest</option></select></label>
</div>
{#if q||shelf||available||subject}<h2 class="catalogue_result-title">Search results</h2>{/if}
{#if error}<p role="alert" class="library-error">{error}</p><button class="library-button" onclick={load}>Try again</button>{:else if !loading&&books.length===0}<div class="catalogue_empty"><h2>{q||shelf||available||subject?'No books found':'Your library starts with a book'}</h2><p>{q||shelf||available||subject?'Try another title, author, subject or shelf.':'Scan a barcode above, or add a book manually.'}</p>{#if q||shelf||available||subject}<button class="library-button secondary" onclick={()=>{shelf='';available='';subject='';clear();}}>Show all books</button>{:else}<a class="library-button" href="/scan/">Add a book</a>{/if}</div>{:else}<div class="catalogue_list" aria-busy={loading}>{#each books as b}<a class="catalogue_book" title={b.title} href={`/books/${b.id}/`}><div class="catalogue_cover" aria-hidden="true">{#if b.cover_url}<img src={b.cover_url} alt="" loading="eager" onerror={(e)=>{const img=e.currentTarget as HTMLImageElement;if(img.getAttribute('src')!==b.cover_url)img.src=b.cover_url;}}/>{:else}<div class="catalogue_missing"><span class="catalogue_missing-label">Cover unavailable</span><span class="catalogue_missing-title">{mainTitle(b.title)}</span><small>{authorLabel(b.authors)}</small></div>{/if}</div>{#if !b.cover_url}<span class="catalogue_missing-state">Cover unavailable.</span>{/if}<div class="catalogue_info"><h3 aria-label={b.title}>{mainTitle(b.title)}</h3>{#if b.subtitle}<p class="catalogue_subtitle">{b.subtitle}</p>{/if}<p class="catalogue_author" title={b.authors.join(', ')}>{authorLabel(b.authors)}</p>{#if sort.startsWith('published_')}{#if b.publication_date}<p class="catalogue_year">Edition published {b.publication_date}</p>{:else}<p class="catalogue_year">Edition date not recorded</p>{/if}{:else if b.first_published_year}<p class="catalogue_year">First published {b.first_published_year}</p>{:else if sort.startsWith('first_published_')}<p class="catalogue_year">First publication year not recorded</p>{/if}<div class="catalogue_meta"><p class="catalogue_status" class:unavailable={b.available===0} class:all-available={b.count===1&&b.available===1}>{b.count===0?'No copies':b.available===0?'On loan':b.available===b.count?'Available':`${b.available} of ${b.count} available`}{#if b.count>1}<small> · {b.count} copies</small>{/if}</p>{#if b.available<b.count||b.count!==1}<span class="catalogue_meta-separator" aria-hidden="true">·</span>{/if}<p class="catalogue_shelf" title={b.copies[0]?.shelf}>{locationLabel(b.copies[0]?.shelf||'No shelf assigned')}</p></div></div></a>{/each}</div>{/if}
{#if total>24}<div class="library-actions catalogue_pagination"><button class="library-button secondary" disabled={page===1||loading} onclick={()=>{page--;load();}}>Previous</button><span>Page {page}</span><button class="library-button secondary" disabled={page*24>=total||loading} onclick={()=>{page++;load();}}>Next</button></div>{/if}
</div>
<style>@layer components {
.catalogue_browse{display:flex;align-items:start;justify-content:space-between;flex-wrap:wrap;gap:1rem}.catalogue_sort{min-width:15rem}.catalogue_subjects{max-width:48rem;flex:1;min-width:min(100%,18rem)}.catalogue_subjects>summary{cursor:pointer;min-height:2.75rem;display:flex;align-items:center;font-weight:600;overflow-wrap:anywhere}.catalogue_subject-body{display:grid;gap:1rem;padding-top:.75rem}.catalogue_subject-body p{font-size:.875rem;color:var(--app-muted);line-height:1.5}.catalogue_subject-list{display:flex;flex-wrap:wrap;gap:.5rem;list-style:none;padding:0}.catalogue_subject-list button{min-height:2.75rem;padding:.5rem .75rem;border:1px solid var(--app-line);background:var(--app-surface);border-radius:.25rem;text-align:left;overflow-wrap:anywhere}.catalogue_subject-list button[aria-pressed=true]{border-color:var(--app-accent);background:var(--app-soft)}.catalogue_subject-list span{font-size:.75rem;color:var(--app-muted);white-space:nowrap}.catalogue_subject-list button:focus-visible{outline:2px solid var(--app-focus);outline-offset:2px}
.catalogue_subtitle{font-size:.9rem;line-height:1.4;color:var(--app-muted);overflow-wrap:anywhere}.catalogue_wrap{display:flex;flex-direction:column;gap:2rem;min-height:calc(100svh - 8rem);max-width:88rem;margin-inline:auto}
.catalogue_header{display:grid;grid-template-columns:minmax(12rem,1fr) minmax(0,40rem) auto;align-items:end;gap:2rem;padding-bottom:0;border-bottom:0}
.catalogue_title{display:flex;align-items:baseline;gap:1rem;align-self:center;flex-wrap:wrap}.catalogue_title h1{font:600 clamp(1.5rem,2.5vw,2rem)/1.15 var(--primary-family);letter-spacing:-.02em}.catalogue_title span{font-size:.875rem;color:var(--app-muted)}
.catalogue_search-group{display:grid;gap:0}.catalogue_label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.catalogue_search{display:flex;align-items:center;gap:.75rem;min-height:3.25rem;padding:.2rem .2rem .2rem 1rem;background:var(--app-surface);border:1px solid var(--app-line);border-radius:.3rem}.catalogue_search.focused{border-color:var(--app-accent);box-shadow:none}
.catalogue_scan-icon{width:1.6rem;height:1.6rem;fill:none;stroke:var(--app-accent);stroke-width:1.4;stroke-linecap:round;flex-shrink:0}.catalogue_input{width:100%;min-width:0;padding:.5rem 0;border:0;background:transparent;outline:none!important;font:1.05rem/1.4 var(--primary-family);color:var(--app-ink)}.catalogue_input::placeholder{color:var(--app-muted)}.catalogue_input::-webkit-search-cancel-button{display:none}
.catalogue_submit,.catalogue_clear{display:grid;place-items:center;min-width:2.75rem;min-height:2.75rem;cursor:pointer;border-radius:.2rem}.catalogue_submit{padding:.5rem 1rem;color:var(--app-surface);background:var(--app-accent);font-size:.875rem;font-weight:600;border:0;border-radius:.2rem}.catalogue_clear{font-size:1.5rem;color:var(--app-muted)}.catalogue_submit:hover{filter:brightness(1.15)}.catalogue_clear:hover{background:var(--app-soft)}.catalogue_submit:focus-visible,.catalogue_clear:focus-visible{outline:2px solid var(--app-focus);outline-offset:2px}
.catalogue_hint{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.catalogue_advanced{position:relative}.catalogue_advanced>summary{display:flex;align-items:center;gap:.5rem;min-height:3.25rem;font-size:.875rem;padding:.5rem 0}.catalogue_advanced>summary::before{display:none!important}.catalogue_advanced summary svg{width:1.2rem;height:1.2rem;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round}.catalogue_filter-dot{width:.35rem;height:.35rem;border-radius:50%;background:var(--app-accent)}.catalogue_filters{position:absolute;right:0;top:calc(100% + .75rem);z-index:20;display:grid;gap:1rem;width:22rem;max-width:calc(100vw - 2rem);padding:1.25rem;background:var(--app-surface);border:1px solid var(--app-line);border-radius:.4rem;box-shadow:var(--app-shadow)}
.catalogue_list{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:3rem 2rem;margin-block:0;align-items:start}.catalogue_book{display:grid;gap:1.25rem;min-width:0;color:var(--app-ink);text-decoration:none}.catalogue_cover{position:relative;display:flex;align-items:end;justify-content:flex-start;height:19rem;min-width:0}.catalogue_cover img{display:block;width:auto;height:100%;max-width:min(100%,12rem);object-fit:contain;object-position:center bottom;filter:drop-shadow(var(--app-shadow));transition:transform 160ms ease}.catalogue_book:hover img{transform:translateY(-4px)}
.catalogue_missing{display:flex;flex-direction:column;align-items:stretch;text-align:left;gap:.65rem;aspect-ratio:2/3;height:100%;max-width:min(100%,12rem);padding:1.5rem 1.25rem;background:var(--app-placeholder);border:1px solid var(--app-line)}.catalogue_missing-state,.catalogue_missing-label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.catalogue_missing-title{padding-top:.5rem;font:500 clamp(1.75rem,2.4vw,2rem)/1.08 var(--app-serif);margin-top:0;overflow-wrap:anywhere}.catalogue_missing small{margin-top:auto;font-size:.75rem;line-height:1.5;color:var(--app-muted)}
.catalogue_info{display:grid;gap:.25rem;min-width:0}.catalogue_info h3{font:600 1rem/1.4 var(--primary-family);letter-spacing:0;overflow-wrap:anywhere}.catalogue_year{font-size:.8125rem;line-height:1.4;color:var(--app-muted);overflow-wrap:anywhere}.catalogue_author{font-size:.875rem;line-height:1.4;color:var(--app-muted)}.catalogue_meta{display:flex;align-items:baseline;flex-wrap:wrap;gap:.2rem .45rem;padding-top:.35rem}.catalogue_meta-separator{color:var(--app-muted)}.catalogue_status{font-size:.75rem;color:var(--app-muted)}.catalogue_status.all-available{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.catalogue_status.unavailable{color:var(--app-ink);font-weight:600}.catalogue_status small{font:inherit}.catalogue_shelf{font-size:.75rem;line-height:1.4;color:var(--app-muted);overflow-wrap:anywhere}
.catalogue_result-title{font:400 1.5rem var(--app-serif)}.catalogue_empty{display:grid;justify-items:start;gap:1rem;padding:3rem 0}.catalogue_empty h2{font:400 1.8rem var(--app-serif)}.catalogue_empty p{color:var(--app-muted)}.catalogue_pagination{padding-top:1.5rem;border-top:1px solid var(--app-line)}
@media(width<70rem){.catalogue_header{gap:1.25rem;grid-template-columns:11rem minmax(0,1fr) auto}.catalogue_list{grid-template-columns:repeat(4,minmax(0,1fr));gap:2.5rem 1.5rem}.catalogue_cover{height:19rem}}
@media(width<56rem){.catalogue_header{grid-template-columns:1fr auto}.catalogue_title{grid-column:1}.catalogue_search-group{grid-column:1/-1;grid-row:2}.catalogue_advanced{grid-column:2;grid-row:1}.catalogue_advanced>summary{min-height:2.75rem}.catalogue_list{grid-template-columns:repeat(3,minmax(0,1fr));margin-block:0}.catalogue_cover{height:18rem}}
@media(width<40rem){.catalogue_wrap{gap:1.75rem;min-height:0}.catalogue_header{gap:1rem}.catalogue_title h1{font-size:1.7rem}.catalogue_search{padding-left:.75rem;gap:.5rem}.catalogue_input{font-size:1rem}.catalogue_submit{padding:.5rem .65rem}.catalogue_label{font-size:.8125rem}.catalogue_list{grid-template-columns:repeat(2,minmax(0,1fr));gap:2rem 1.25rem}.catalogue_cover{height:14rem}.catalogue_missing{padding:.8rem;gap:.5rem}.catalogue_missing-title{font-size:1.35rem}.catalogue_missing small{font-size:.65rem}.catalogue_info h3{font-size:.9375rem}.catalogue_author{font-size:.8rem}.catalogue_status,.catalogue_shelf{font-size:.75rem}}
@media(width<23rem){.catalogue_cover{height:12rem}.catalogue_scan-icon{display:none}.catalogue_missing-label{font-size:.6rem}}
}</style>
